966	    /**
967	     * Puts the process record in the map.
968	     * <p>NOTE: Callers should avoid acquiring the mPidsSelfLocked lock before calling this
969	     * method.
970	     */
971	    @GuardedBy("this")
972	    void addPidLocked(ProcessRecord app) {
973	        final int pid = app.getPid();
974	        synchronized (mPidsSelfLocked) {
975	            mPidsSelfLocked.doAddInternal(pid, app);
976	        }
977	        synchronized (sActiveProcessInfoSelfLocked) {
978	            if (app.processInfo != null) {
979	                sActiveProcessInfoSelfLocked.put(pid, app.processInfo);
980	            } else {
981	                sActiveProcessInfoSelfLocked.remove(pid);
982	            }
983	        }
984	        mAtmInternal.onProcessMapped(pid, app.getWindowProcessController());
985	    }
