987	    /**
988	     * Removes the process record from the map.
989	     * <p>NOTE: Callers should avoid acquiring the mPidsSelfLocked lock before calling this
990	     * method.
991	     */
992	    @GuardedBy("this")
993	    boolean removePidLocked(int pid, ProcessRecord app) {
994	        final boolean removed;
995	        synchronized (mPidsSelfLocked) {
996	            removed = mPidsSelfLocked.doRemoveInternal(pid, app);
997	        }
998	        if (removed) {
999	            synchronized (sActiveProcessInfoSelfLocked) {
1000	                sActiveProcessInfoSelfLocked.remove(pid);
1001	            }
1002	            mAtmInternal.onProcessUnMapped(pid);
1003	        }
1004	        return removed;
1005	    }
