2330	        public void registerObserver() {
2331	            mContext.getContentResolver().registerContentObserver(
2332	                    Settings.Global.getUriFor(Settings.Global.HIDDEN_API_BLACKLIST_EXEMPTIONS),
2333	                    false,
2334	                    this);
2335	            mContext.getContentResolver().registerContentObserver(
2336	                    Settings.Global.getUriFor(Settings.Global.HIDDEN_API_POLICY),
2337	                    false,
2338	                    this);
2339	            DeviceConfig.addOnPropertiesChangedListener(DeviceConfig.NAMESPACE_APP_COMPAT,
2340	                    mContext.getMainExecutor(), this);
2341	            update();
