2344	        private void update() {
2345	            String exemptions = Settings.Global.getString(mContext.getContentResolver(),
2346	                    Settings.Global.HIDDEN_API_BLACKLIST_EXEMPTIONS);
2347	            if (!TextUtils.equals(exemptions, mExemptionsStr)) {
2348	                mExemptionsStr = exemptions;
2349	                if ("*".equals(exemptions)) {
2350	                    mBlacklistDisabled = true;
2351	                    mExemptions = Collections.emptyList();
2352	                } else {
2353	                    mBlacklistDisabled = false;
2354	                    mExemptions = TextUtils.isEmpty(exemptions)
2355	                            ? Collections.emptyList()
2356	                            : Arrays.asList(exemptions.split(","));
2357	                }
2358	                if (!ZYGOTE_PROCESS.setApiDenylistExemptions(mExemptions)) {
2359	                  Slog.e(TAG, "Failed to set API blacklist exemptions!");
2360	                  // leave mExemptionsStr as is, so we don't try to send the same list again.
2361	                  mExemptions = Collections.emptyList();
2362	                }
2363	            }
2364	            mPolicy = getValidEnforcementPolicy(Settings.Global.HIDDEN_API_POLICY);
2365	        }
