2369	                    ApplicationInfo.HIDDEN_API_ENFORCEMENT_DEFAULT);
2370	            if (ApplicationInfo.isValidHiddenApiEnforcementPolicy(policy)) {
2371	                return policy;
2372	            } else {
2373	                return ApplicationInfo.HIDDEN_API_ENFORCEMENT_DEFAULT;
2374	            }
2375	        }
