2634	    /**
2635	     * Returns true if the package {@code pkg1} running under user handle {@code uid1} is
2636	     * allowed association with the package {@code pkg2} running under user handle {@code uid2}.
2637	     * <p> If either of the packages are running as  part of the core system, then the
2638	     * association is implicitly allowed.
2639	     */
2640	    boolean validateAssociationAllowedLocked(String pkg1, int uid1, String pkg2, int uid2) {
2641	        ensureAllowedAssociations();
2642	        // Interactions with the system uid are always allowed, since that is the core system
2643	        // that everyone needs to be able to interact with. Also allow reflexive associations
2644	        // within the same uid.
2645	        if (uid1 == uid2 || UserHandle.getAppId(uid1) == SYSTEM_UID
2646	                || UserHandle.getAppId(uid2) == SYSTEM_UID) {
2647	            return true;
2648	        }
2649	
2650	        // Check for association on both source and target packages.
2651	        PackageAssociationInfo pai = mAllowedAssociations.get(pkg1);
2652	        if (pai != null && !pai.isPackageAssociationAllowed(pkg2)) {
2653	            return false;
2654	        }
2655	        pai = mAllowedAssociations.get(pkg2);
2656	        if (pai != null && !pai.isPackageAssociationAllowed(pkg1)) {
2657	            return false;
2658	        }
2659	        // If no explicit associations are provided in the manifest, then assume the app is
2660	        // allowed associations with any package.
2661	        return true;
2662	    }
