2701	    public boolean onTransact(int code, Parcel data, Parcel reply, int flags)
2702	            throws RemoteException {
2703	        if (code == SYSPROPS_TRANSACTION) {
2704	            // We need to tell all apps about the system property change.
2705	            ArrayList<IBinder> procs = new ArrayList<IBinder>();
2706	            synchronized (mProcLock) {
2707	                final ArrayMap<String, SparseArray<ProcessRecord>> pmap =
2708	                        mProcessList.getProcessNamesLOSP().getMap();
2709	                final int numOfNames = pmap.size();
2710	                for (int ip = 0; ip < numOfNames; ip++) {
2711	                    SparseArray<ProcessRecord> apps = pmap.valueAt(ip);
2712	                    final int numOfApps = apps.size();
2713	                    for (int ia = 0; ia < numOfApps; ia++) {
2714	                        ProcessRecord app = apps.valueAt(ia);
2715	                        final IApplicationThread thread = app.getThread();
2716	                        if (thread != null) {
2717	                            procs.add(thread.asBinder());
2718	                        }
2719	                    }
2720	                }
2721	            }
2722	
2723	            int N = procs.size();
2724	            for (int i=0; i<N; i++) {
2725	                Parcel data2 = Parcel.obtain();
2726	                try {
2727	                    procs.get(i).transact(IBinder.SYSPROPS_TRANSACTION, data2, null,
2728	                            Binder.FLAG_ONEWAY);
2729	                } catch (RemoteException e) {
2730	                }
2731	                data2.recycle();
2732	            }
2733	        }
2734	        try {
2735	            return super.onTransact(code, data, reply, flags);
2736	        } catch (RuntimeException e) {
2737	            // The activity manager only throws certain exceptions intentionally, so let's
2738	            // log all others.
2739	            if (!(e instanceof SecurityException
2740	                    || e instanceof IllegalArgumentException
2741	                    || e instanceof IllegalStateException)) {
2742	                Slog.wtf(TAG, "Activity Manager Crash."
2743	                        + " UID:" + Binder.getCallingUid()
2744	                        + " PID:" + Binder.getCallingPid()
2745	                        + " TRANS:" + code, e);
2746	            }
2747	            throw e;
2748	        }
2749	    }
