7697	    /**
7698	     * Takes a bugreport using bug report API ({@code BugreportManager}) which gets
7699	     * triggered by sending a broadcast to Shell. Optionally adds an extra attachment.
7700	     */
7701	    public void requestBugReportWithDescription(@Nullable String shareTitle,
7702	            @Nullable String shareDescription, int bugreportType, long nonce,
7703	            @Nullable List<Uri> extraAttachments) {
7704	        String type = null;
7705	        switch (bugreportType) {
7706	            case BugreportParams.BUGREPORT_MODE_FULL:
7707	                type = "bugreportfull";
7708	                break;
7709	            case BugreportParams.BUGREPORT_MODE_INTERACTIVE:
7710	                type = "bugreportplus";
7711	                break;
7712	            case BugreportParams.BUGREPORT_MODE_REMOTE:
7713	                type = "bugreportremote";
7714	                break;
7715	            case BugreportParams.BUGREPORT_MODE_WEAR:
7716	                type = "bugreportwear";
7717	                break;
7718	            case BugreportParams.BUGREPORT_MODE_TELEPHONY:
7719	                type = "bugreporttelephony";
7720	                break;
7721	            case BugreportParams.BUGREPORT_MODE_WIFI:
7722	                type = "bugreportwifi";
7723	                break;
7724	            case BugreportParams.BUGREPORT_MODE_ONBOARDING:
7725	                type = "bugreportonboarding";
7726	                break;
7727	            default:
7728	                throw new IllegalArgumentException(
7729	                    "Provided bugreport type is not correct, value: "
7730	                        + bugreportType);
7731	        }
7732	        // Always log caller, even if it does not have permission to dump.
7733	        Slog.i(TAG, type + " requested by UID " + Binder.getCallingUid());
7734	        enforceCallingPermission(android.Manifest.permission.DUMP, "requestBugReport");
7735	
7736	        if (!TextUtils.isEmpty(shareTitle)) {
7737	            if (shareTitle.length() > MAX_BUGREPORT_TITLE_SIZE) {
7738	                String errorStr = "shareTitle should be less than "
7739	                        + MAX_BUGREPORT_TITLE_SIZE + " characters";
7740	                throw new IllegalArgumentException(errorStr);
7741	            }
7742	            if (!TextUtils.isEmpty(shareDescription)) {
7743	                if (shareDescription.length() > MAX_BUGREPORT_DESCRIPTION_SIZE) {
7744	                    String errorStr = "shareDescription should be less than "
7745	                            + MAX_BUGREPORT_DESCRIPTION_SIZE + " characters";
7746	                    throw new IllegalArgumentException(errorStr);
7747	                }
7748	            }
7749	            Slog.d(TAG, "Bugreport notification title " + shareTitle
7750	                    + " description " + shareDescription);
7751	        }
7752	        // Create intent to trigger Bugreport API via Shell
7753	        Intent triggerShellBugreport = new Intent();
7754	        triggerShellBugreport.setAction(INTENT_BUGREPORT_REQUESTED);
7755	        triggerShellBugreport.setPackage(SHELL_APP_PACKAGE);
7756	        triggerShellBugreport.putExtra(EXTRA_BUGREPORT_TYPE, bugreportType);
7757	        triggerShellBugreport.putExtra(EXTRA_BUGREPORT_NONCE, nonce);
7758	        if (extraAttachments != null && !extraAttachments.isEmpty()) {
7759	            triggerShellBugreport.putParcelableArrayListExtra(EXTRA_EXTRA_ATTACHMENT_URIS,
7760	                    new ArrayList(extraAttachments));
7761	            triggerShellBugreport.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
7762	        }
7763	        triggerShellBugreport.addFlags(Intent.FLAG_RECEIVER_FOREGROUND);
7764	        triggerShellBugreport.addFlags(Intent.FLAG_RECEIVER_INCLUDE_BACKGROUND);
7765	        if (shareTitle != null) {
7766	            triggerShellBugreport.putExtra(EXTRA_TITLE, shareTitle);
7767	        }
7768	        if (shareDescription != null) {
7769	            triggerShellBugreport.putExtra(EXTRA_DESCRIPTION, shareDescription);
7770	        }
7771	        final long identity = Binder.clearCallingIdentity();
7772	        try {
7773	            // Send broadcast to shell to trigger bugreport using Bugreport API
7774	            // Always start the shell process on the current user to ensure that
7775	            // the foreground user can see all bugreport notifications.
7776	            // In case of BUGREPORT_MODE_REMOTE send the broadcast to SYSTEM user as the device
7777	            // owner apps are running on the SYSTEM user.
7778	            if (bugreportType == BugreportParams.BUGREPORT_MODE_REMOTE) {
7779	                mContext.sendBroadcastAsUser(triggerShellBugreport, UserHandle.SYSTEM);
7780	            } else {
7781	                mContext.sendBroadcastAsUser(triggerShellBugreport,
7782	                        getCurrentUser().getUserHandle());
7783	            }
7784	        } finally {
7785	            Binder.restoreCallingIdentity(identity);
7786	        }
7787	    }
