16591	        private boolean bindSdkSandboxServiceInternal(Intent service, ServiceConnection conn,
16592	                int clientAppUid, IBinder clientApplicationThread, String clientAppPackage,
16593	                String processName, long flags)
16594	                throws RemoteException {
16595	            validateSdkSandboxParams(service, clientAppUid, clientAppPackage, processName);
16596	            if (mAppOpsService.checkPackage(clientAppUid, clientAppPackage)
16597	                    != AppOpsManager.MODE_ALLOWED) {
16598	                throw new IllegalArgumentException("uid does not belong to provided package");
16599	            }
16600	            if (conn == null) {
16601	                throw new IllegalArgumentException("connection is null");
16602	            }
16603	
16604	            Handler handler = mContext.getMainThreadHandler();
16605	            IApplicationThread clientApplicationThreadVerified = null;
16606	            if (clientApplicationThread != null) {
16607	                // Make sure this is a valid application process
16608	                synchronized (this) {
16609	                    final ProcessRecord rec = getRecordForAppLOSP(clientApplicationThread);
16610	                    if (rec == null) {
16611	                        // This could happen if the calling process has disappeared; no need for the
16612	                        // sandbox to be even started in this case.
16613	                        Slog.i(TAG, "clientApplicationThread process not found.");
16614	                        return false;
16615	                    }
16616	                    if (rec.info.uid != clientAppUid) {
16617	                        throw new IllegalArgumentException("clientApplicationThread does not match "
16618	                                + " client uid");
16619	                    }
16620	                    clientApplicationThreadVerified = rec.getThread();
16621	                }
16622	            }
16623	            final IServiceConnection sd = mContext.getServiceDispatcher(conn, handler,
16624	                    flags);
16625	            service.prepareToLeaveProcess(mContext);
16626	            return ActivityManagerService.this.bindServiceInstance(
16627	                    mContext.getIApplicationThread(), mContext.getActivityToken(), service,
16628	                    service.resolveTypeIfNeeded(mContext.getContentResolver()), sd,
16629	                    flags,
16630	                    processName, /*isSdkSandboxService*/ true, clientAppUid, clientAppPackage,
16631	                    clientApplicationThreadVerified, mContext.getOpPackageName(),
16632	                    UserHandle.getUserId(clientAppUid)) != 0;
16633	        }
