16635	        private void validateSdkSandboxParams(Intent service, int clientAppUid,
16636	                String clientAppPackage, String processName) {
16637	            if (service == null) {
16638	                throw new IllegalArgumentException("intent is null");
16639	            }
16640	            if (clientAppPackage == null) {
16641	                throw new IllegalArgumentException("clientAppPackage is null");
16642	            }
16643	            if (processName == null) {
16644	                throw new IllegalArgumentException("processName is null");
16645	            }
16646	            if (service.getComponent() == null) {
16647	                throw new IllegalArgumentException("service must specify explicit component");
16648	            }
16649	            if (!UserHandle.isApp(clientAppUid)) {
16650	                throw new IllegalArgumentException("uid is not within application range");
16651	            }
16652	        }
