16701	        @Override
16702	        public void killForegroundAppsForUser(@UserIdInt int userId) {
16703	            final ArrayList<ProcessRecord> procs = new ArrayList<>();
16704	            synchronized (mProcLock) {
16705	                final int numOfProcs = mProcessList.getProcessNamesLOSP().getMap().size();
16706	                for (int ip = 0; ip < numOfProcs; ip++) {
16707	                    final SparseArray<ProcessRecord> apps =
16708	                            mProcessList.getProcessNamesLOSP().getMap().valueAt(ip);
16709	                    final int NA = apps.size();
16710	                    for (int ia = 0; ia < NA; ia++) {
16711	                        final ProcessRecord app = apps.valueAt(ia);
16712	                        if (app.isPersistent()) {
16713	                            // We don't kill persistent processes.
16714	                            continue;
16715	                        }
16716	                        if (app.isRemoved()
16717	                                || (app.userId == userId && app.mState.hasForegroundActivities())) {
16718	                            procs.add(app);
16719	                        }
16720	                    }
16721	                }
16722	            }
16723	
16724	            final int numOfProcs = procs.size();
16725	            if (numOfProcs > 0) {
16726	                synchronized (ActivityManagerService.this) {
16727	                    for (int i = 0; i < numOfProcs; i++) {
16728	                        mProcessList.removeProcessLocked(procs.get(i), false, true,
16729	                                ApplicationExitInfo.REASON_OTHER,
16730	                                ApplicationExitInfo.SUBREASON_KILL_ALL_FG,
16731	                                "kill all fg");
16732	                    }
16733	                }
16734	            }
16735	        }
