17717	        @Override
17718	        public void addPendingTopUid(int uid, int pid, @Nullable IApplicationThread thread) {
17719	            final boolean isNewPending = mPendingStartActivityUids.add(uid, pid);
17720	            // If the next top activity is in cached and frozen mode, WM should raise its priority
17721	            // to unfreeze it. This is done by calling AMS.updateOomAdj that will lower its oom adj.
17722	            // However, WM cannot hold the AMS clock here so the updateOomAdj operation is performed
17723	            // in a separate thread asynchronously. Therefore WM can't guarantee AMS will unfreeze
17724	            // next top activity on time. This race will fail the following binder transactions WM
17725	            // sends to the activity. After this race issue between WM/ATMS and AMS is solved, this
17726	            // workaround can be removed. (b/213288355)
17727	            if (isNewPending) {
17728	                mOomAdjuster.mCachedAppOptimizer.unfreezeProcess(pid, OOM_ADJ_REASON_ACTIVITY);
17729	            }
17730	            // We need to update the network rules for the app coming to the top state so that
17731	            // it can access network when the device or the app is in a restricted state
17732	            // (e.g. battery/data saver) but since waiting for updateOomAdj to complete and then
17733	            // informing NetworkPolicyManager might get delayed, informing the state change as soon
17734	            // as we know app is going to come to the top state.
17735	            if (isNewPending && mNetworkPolicyUidObserver != null) {
17736	                try {
17737	                    final long procStateSeq = mProcessList.getNextProcStateSeq();
17738	                    mNetworkPolicyUidObserver.onUidStateChanged(uid, PROCESS_STATE_TOP,
17739	                            procStateSeq, PROCESS_CAPABILITY_ALL);
17740	                    if (thread != null && shouldWaitForNetworkRulesUpdate(uid)) {
17741	                        thread.setNetworkBlockSeq(procStateSeq);
17742	                    }
17743	                } catch (RemoteException e) {
17744	                    Slog.d(TAG, "Error calling setNetworkBlockSeq", e);
17745	                }
17746	            }
17747	        }
17748	
17749	        private boolean shouldWaitForNetworkRulesUpdate(int uid) {
17750	            synchronized (mUidNetworkBlockedReasons) {
17751	                // TODO: We can reuse this data in
17752	                // ProcessList#incrementProcStateSeqAndNotifyAppsLOSP instead of calling into
17753	                // NetworkManagementService.
17754	                final int uidBlockedReasons = mUidNetworkBlockedReasons.get(
17755	                        uid, BLOCKED_REASON_NONE);
17756	                // We should only inform the uid to block if it is currently blocked but will be
17757	                // unblocked once it comes to the TOP state.
17758	                return uidBlockedReasons != BLOCKED_REASON_NONE
17759	                        && updateBlockedReasonsWithProcState(uidBlockedReasons, PROCESS_STATE_TOP)
17760	                        == BLOCKED_REASON_NONE;
17761	            }
17762	        }
