17787	        @Override
17788	        public PendingIntent getPendingIntentActivityAsApp(
17789	                int requestCode, @NonNull Intent[] intents, int flags, Bundle options,
17790	                String ownerPkg, int ownerUid) {
17791	            // system callers must explicitly set mutability state
17792	            final boolean flagImmutableSet = (flags & PendingIntent.FLAG_IMMUTABLE) != 0;
17793	            final boolean flagMutableSet = (flags & PendingIntent.FLAG_MUTABLE) != 0;
17794	            if (flagImmutableSet == flagMutableSet) {
17795	                throw new IllegalArgumentException(
17796	                        "Must set exactly one of FLAG_IMMUTABLE or FLAG_MUTABLE");
17797	            }
17798	
17799	            final Context context = ActivityManagerService.this.mContext;
17800	            final ContentResolver resolver = context.getContentResolver();
17801	            final int len = intents.length;
17802	            final String[] resolvedTypes = new String[len];
17803	            for (int i = 0; i < len; i++) {
17804	                final Intent intent = intents[i];
17805	                resolvedTypes[i] = intent.resolveTypeIfNeeded(resolver);
17806	                intent.migrateExtraStreamToClipData(context);
17807	                intent.prepareToLeaveProcess(context);
17808	            }
17809	            IIntentSender target =
17810	                    ActivityManagerService.this.getIntentSenderWithFeatureAsApp(
17811	                            INTENT_SENDER_ACTIVITY, ownerPkg,
17812	                            context.getAttributionTag(), null, null, requestCode,
17813	                            intents,
17814	                            resolvedTypes,
17815	                            flags, options, UserHandle.getUserId(ownerUid), ownerUid);
17816	            return target != null ? new PendingIntent(target) : null;
