18880	                return null;
18881	            }
18882	            boolean hasDefaultDisplay = false;
18883	            for (Display display : allDisplays) {
18884	                if (display.getDisplayId() == Display.DEFAULT_DISPLAY) {
18885	                    hasDefaultDisplay = true;
18886	                    break;
18887	                }
18888	            }
18889	            if (!hasDefaultDisplay) {
18890	                Slogf.wtf(TAG, "displayManager (%s) has %d displays (%s), but none has id "
18891	                        + "DEFAULT_DISPLAY (%d)", displayManager, allDisplays.length,
18892	                        Arrays.toString(allDisplays), Display.DEFAULT_DISPLAY);
18893	                return null;
18894	            }
18895	
18896	            boolean allowOnDefaultDisplay = UserManager
18897	                    .isVisibleBackgroundUsersOnDefaultDisplayEnabled();
18898	            int displaysSize = allDisplays.length;
18899	            if (!allowOnDefaultDisplay) {
18900	                displaysSize--;
18901	            }
18902	            int[] displayIds = new int[displaysSize];
18903	
18904	            int numberValidDisplays = 0;
18905	            for (Display display : allDisplays) {
18906	                int displayId = display.getDisplayId();
18907	                // TODO(b/247592632): check other properties like isSecure or proper display type
18908	                if (display.isValid() && ((display.getFlags() & Display.FLAG_PRIVATE) == 0)
18909	                        && (allowOnDefaultDisplay || displayId != Display.DEFAULT_DISPLAY)) {
18910	                    displayIds[numberValidDisplays++] = displayId;
18911	                }
18912	            }
18913	
18914	            if (numberValidDisplays == 0) {
18915	                // TODO(b/247580038): remove this workaround once a virtual display on Car's
18916	                // KitchenSink (or other app) can be used while running CTS tests on devices that
18917	                // don't have a real display.
18918	                // STOPSHIP: if not removed, it should at least be unit tested
18919	                String testingProp = "fw.display_ids_for_starting_users_for_testing_purposes";
18920	                int displayId = SystemProperties.getInt(testingProp, Display.DEFAULT_DISPLAY);
18921	                if (allowOnDefaultDisplay && displayId == Display.DEFAULT_DISPLAY
18922	                        || displayId > 0) {
18923	                    Slogf.w(TAG, "getDisplayIdsForStartingVisibleBackgroundUsers(): no valid "
18924	                            + "display found, but returning %d as set by property %s", displayId,
18925	                            testingProp);
18926	                    return new int[] { displayId };
18927	                }
18928	                Slogf.e(TAG, "getDisplayIdsForStartingVisibleBackgroundUsers(): no valid display"
18929	                        + " on %s", Arrays.toString(allDisplays));
18930	                return null;
18931	            }
18932	
18933	            if (numberValidDisplays != displayIds.length) {
18934	                int[] validDisplayIds = new int[numberValidDisplays];
18935	                System.arraycopy(displayIds, 0, validDisplayIds, 0, numberValidDisplays);
18936	                if (DEBUG_MU) {
18937	                    Slogf.d(TAG, "getDisplayIdsForStartingVisibleBackgroundUsers(): returning "
18938	                            + "only valid displays (%d instead of %d): %s", numberValidDisplays,
18939	                            displayIds.length, Arrays.toString(validDisplayIds));
18940	                }
18941	                return validDisplayIds;
18942	            }
18943	
18944	            if (DEBUG_MU) {
18945	                Slogf.d(TAG, "getDisplayIdsForStartingVisibleBackgroundUsers(): returning all (but "
18946	                        + "DEFAULT_DISPLAY) displays : %s", Arrays.toString(displayIds));
18947	            }
18948	            return displayIds;
18949	        }
